function getModuleByUrl(url) {
        if (url) {
            url = normalize(url);
            return moduleCache.get(url);  // Kuro: Object -> Map
        }
    }

loader.normalize_text:
function normalize(name) {
        if ('./' === name.substr(0,2)) {
            name = name.substr(2);
        }
        return name;
    }
